-- >>> 20261124000000_customer_portal_lockdown.sql
-- Customer portal lockdown.
-- 1) One login <-> one customer row (a customer row can never be shared by two logins).
create unique index if not exists customers_auth_user_uq on customers (auth_user_id) where auth_user_id is not null;

-- 2) cust_self_update lets a website customer UPDATE their own row, which until now included identity/ownership
--    columns (auth_user_id, org_id, codes, status, tags, notes, referral links). Freeze those for non-staff.
create or replace function public.customers_protect_cols() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or current_setting('role', true) = 'service_role' then return new; end if;   -- server/service paths
  if public.current_org() is not null then return new; end if;                                       -- approved staff
  if new.auth_user_id is distinct from old.auth_user_id or new.org_id is distinct from old.org_id
     or new.customer_code is distinct from old.customer_code or new.vision_id is distinct from old.vision_id
     or new.status is distinct from old.status or new.tags is distinct from old.tags
     or new.notes is distinct from old.notes or new.branch_id is distinct from old.branch_id
     or new.referral_code is distinct from old.referral_code or new.referred_by_customer is distinct from old.referred_by_customer
     or new.gstin is distinct from old.gstin or new.created_at is distinct from old.created_at then
    raise exception 'These customer fields can only be changed by the store';
  end if;
  return new;
end $$;

drop trigger if exists trg_customers_protect_cols on customers;

create trigger trg_customers_protect_cols before update on customers for each row execute function public.customers_protect_cols();


-- >>> 20261125010000_fix_patient_customer_id.sql
-- ─── Fix: POS cannot place an order — sales.patient_customer_id ────────────────────
--
-- Symptom at the counter: pressing Pay in the POS returns
--   "That field could not be saved — the app may be out of date.
--    Reload the page and try again."
-- for every order, so no sale can be created.
--
-- Cause: sales.patient_customer_id and lab_orders.patient_customer_id exist in the
-- database as NOT NULL with no default, but nothing ever writes them — place_sale()
-- (the one RPC every POS and website order goes through) does not list them in its
-- INSERT. Postgres therefore rejects the very first statement of place_sale with
--
--   null value in column "patient_customer_id" of relation "sales"
--   violates not-null constraint
--
-- and errors.ts maps `column "..." of relation` to the message above, which is why
-- a not-null violation is reported as a stale-schema problem.
--
-- The patient is the person the lenses are for. At the counter that is the customer
-- the sale is being rung up for, which is exactly the value the pre-existing sales
-- rows already hold (patient_customer_id = customer_id on ORD-0001..0004). So the
-- column is back-filled rather than relaxed: the NOT NULL invariant stays true for
-- every writer — place_sale today, and any direct insert tomorrow — without having
-- to keep editing the place_sale body (it is rewritten by several migrations).

create or replace function public.fill_patient_customer_id() returns trigger
language plpgsql as $$
begin
  new.patient_customer_id := coalesce(new.patient_customer_id, new.customer_id);
  return new;
end $$;

-- Postgres has no CREATE TRIGGER IF NOT EXISTS, hence the DO block.
do $$
begin
  drop trigger if exists trg_sales_patient on sales;
  create trigger trg_sales_patient
    before insert on sales
    for each row execute function public.fill_patient_customer_id();

  drop trigger if exists trg_lab_orders_patient on lab_orders;
  create trigger trg_lab_orders_patient
    before insert on lab_orders
    for each row execute function public.fill_patient_customer_id();
end $$;


