-- >>> 20261126000000_branch_read_wide_write_narrow.sql
-- Phase 1 RBAC: READ WIDE, WRITE NARROW.
--  * Customer-facing history (sales, lines, payments, lab, repairs, eye exams, stock availability) is READABLE across all
--    branches of the organisation, so Branch B can serve a customer who bought at Branch A.
--  * Writing is still limited to branches the user belongs to (home branch, permanent extra branches, or a temporary assignment).
--  * Branch-private money data (cashbook, expenses, day closing, purchases, credit notes, stock movements) stays branch-scoped.
--  * Staff can belong to several branches permanently (profile_branches), managed only through an admin RPC.

-- 1. Permanent multi-branch membership ---------------------------------------------------------------------------
create table if not exists profile_branches (
  profile_id uuid not null references profiles(id) on delete cascade,
  branch_id  uuid not null references branches(id) on delete cascade,
  org_id     uuid not null references organizations(id),
  created_by uuid default auth.uid(), created_at timestamptz not null default now(),
  primary key (profile_id, branch_id));

create index if not exists idx_profile_branches_branch on profile_branches (branch_id);

alter table profile_branches enable row level security;

drop policy if exists pb_sel on profile_branches;

create policy pb_sel on profile_branches for select to authenticated
  using (org_id = public.current_org() and (profile_id = auth.uid() or public.is_manager()));

revoke insert, update, delete on profile_branches from anon, authenticated;

-- writes only via set_profile_branches()

create or replace function public.can_access_branch(b uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select exists (select 1 from branches br where br.id = b and br.org_id = p.org_id) and (
      p.role_key in ('owner', 'admin') or p.branch_id = b
      or exists (select 1 from profile_branches pb where pb.profile_id = p.id and pb.branch_id = b)
      or exists (select 1 from staff_assignments a where a.profile_id = p.id and a.branch_id = b
                 and a.revoked_at is null and a.starts_at <= now() and a.ends_at > now()))
    from profiles p where p.id = auth.uid() and p.is_approved and not p.deactivated), false) $$;

create or replace function public.set_profile_branches(p_profile uuid, p_branches uuid[]) returns void
language plpgsql security definer set search_path = public as $$
declare c profiles; t profiles; b uuid;
begin
  select * into c from profiles where id = auth.uid() and is_approved and not deactivated;
  if not found or c.role_key not in ('owner', 'admin') then raise exception 'Only an owner or admin can change branch access' using errcode = '42501'; end if;
  select * into t from profiles where id = p_profile and org_id = c.org_id;
  if not found then raise exception 'Staff member not found'; end if;
  if t.role_key in ('owner', 'admin') then raise exception 'Owners and admins already see every branch'; end if;
  foreach b in array coalesce(p_branches, '{}') loop
    if not exists (select 1 from branches where id = b and org_id = c.org_id and is_active) then raise exception 'Branch not in your organisation'; end if;
  end loop;
  delete from profile_branches where profile_id = p_profile and branch_id <> all (coalesce(p_branches, '{}'));
  insert into profile_branches (profile_id, branch_id, org_id) select p_profile, x, c.org_id from unnest(coalesce(p_branches, '{}')) x
    on conflict do nothing;
  insert into audit_log (org_id, user_id, table_name, action, new_data)
    values (c.org_id, auth.uid(), 'profile_branches', 'set', jsonb_build_object('profile', p_profile, 'branches', p_branches));
end $$;

revoke all on function public.set_profile_branches(uuid, uuid[]) from public, anon;

grant execute on function public.set_profile_branches(uuid, uuid[]) to authenticated;

-- 2. Cross-branch READ for customer history & stock availability ----------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['sales', 'lab_orders', 'repairs', 'eye_examinations', 'stock'] loop
    continue when to_regclass('public.' || t) is null;
    execute format('drop policy if exists %I on %I', t || '_rls_sel', t);
    execute format('create policy %I on %I for select to authenticated using (org_id = public.current_org())', t || '_rls_sel', t);
  end loop;
end $$;

-- 3. Child rows: readable with the parent, but WRITABLE only when the parent's branch is accessible --------------------
do $$
declare r record; chk text;
begin
  for r in select * from (values ('sale_lines', 'sale_id', 'sales'), ('payments', 'sale_id', 'sales'),
                                 ('repair_events', 'repair_id', 'repairs'), ('lab_events', 'lab_order_id', 'lab_orders')) v(t, fk, par) loop
    continue when to_regclass('public.' || r.t) is null;
    chk := format('org_id = public.current_org() and exists (select 1 from %I par where par.id = %I and public.can_access_branch(par.branch_id))', r.par, r.fk);
    execute format('drop policy if exists %I on %I', r.t || '_rls_ins', r.t);
    execute format('create policy %I on %I for insert to authenticated with check (%s)', r.t || '_rls_ins', r.t, chk);
    if r.t in ('sale_lines', 'payments') then
      execute format('drop policy if exists %I on %I', r.t || '_rls_upd', r.t);
      execute format('create policy %I on %I for update to authenticated using (%s) with check (%s)', r.t || '_rls_upd', r.t, chk, chk);
    end if;
  end loop;
end $$;

-- 4. "Customer from another branch" context for the POS banner. SECURITY INVOKER: it only reveals what RLS already allows.
create or replace function public.customer_branch_context(p_customer uuid) returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'branches_visited', (select count(distinct s.branch_id) from sales s where s.customer_id = p_customer),
    'sale_count',       (select count(*) from sales s where s.customer_id = p_customer),
    'lifetime_value',   (select coalesce(sum(s.grand_total), 0) from sales s where s.customer_id = p_customer),
    'last_sale',        (select jsonb_build_object('branch_id', s.branch_id, 'branch', b.name, 'at', s.created_at, 'amount', s.grand_total, 'mine', public.can_access_branch(s.branch_id))
                           from sales s join branches b on b.id = s.branch_id where s.customer_id = p_customer order by s.created_at desc limit 1)) $$;

grant execute on function public.customer_branch_context(uuid) to authenticated;


-- >>> 20261126010000_fix_place_sale_array_operator.sql
-- ─── Fix: place_sale uses an array `+` operator PostgreSQL does not have ────────────
--
-- Symptom: once sales.patient_customer_id is back-filled, pressing Pay in the POS
-- fails again, this time with
--   operator does not exist: uuid[] + uuid[]
-- for any bag containing a product or accessory, so orders still cannot be placed.
--
-- Cause: migration 0041_place_sale_restore.sql line 211 writes
--   v_product_ids := v_product_ids + array[v_pid];
-- PostgreSQL has no `+` for arrays — only `||` and array_append(). The statement is
-- reached once per product/accessory line of an order, so place_sale aborts and the
-- whole sale rolls back.
--
-- v_product_ids is written but never read anywhere in the function, so the line is
-- dead weight. It is corrected to `||` rather than deleted so the intent (accumulate
-- the products this sale touched) survives if someone starts reading it.
--
-- The patch is applied to whichever place_sale body is live rather than pasting a
-- fresh copy of the whole function: place_sale is rewritten by nine migrations and
-- by hand, and a pasted copy would silently revert any unrelated fix applied since.
-- Idempotent — a second run finds nothing to replace and does nothing.

do $$
declare
  v_def text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'place_sale' and p.prokind = 'f';

  if v_def is null then
    raise exception 'place_sale() not found in schema public';
  end if;

  if position('v_product_ids + array[v_pid]' in v_def) = 0 then
    return;   -- already fixed, or the line is gone: nothing to do
  end if;

  v_def := replace(v_def, 'v_product_ids + array[v_pid]', 'v_product_ids || array[v_pid]');
  execute rtrim(v_def, E'\n;');   -- pg_get_functiondef() trails a semicolon EXECUTE does not want
end $$;


-- >>> 20261126020000_product_costs.sql
-- Cost price is commercially sensitive: move it out of `products` (readable by every staff member) into a table that only
-- managers, admins and owners can read or write. Sales staff keep full access to everything else about a product.
create table if not exists product_costs (
  product_id uuid primary key references products(id) on delete cascade,
  org_id uuid not null default public.current_org() references organizations(id),
  cost_price numeric(10,2) check (cost_price is null or cost_price >= 0),
  updated_by uuid default auth.uid(), updated_at timestamptz not null default now());

alter table product_costs enable row level security;

create policy pc_sel on product_costs for select to authenticated using (org_id = public.current_org() and public.is_manager());

create policy pc_ins on product_costs for insert to authenticated with check (org_id = public.current_org() and public.is_manager());

create policy pc_upd on product_costs for update to authenticated using (org_id = public.current_org() and public.is_manager()) with check (org_id = public.current_org() and public.is_manager());

create policy pc_del on product_costs for delete to authenticated using (org_id = public.current_org() and public.is_manager());

-- A cost can only attach to a product of the same organisation.
create or replace function public.product_costs_guard() returns trigger language plpgsql as $$
begin
  if not exists (select 1 from products p where p.id = new.product_id and p.org_id = new.org_id) then raise exception 'Product not in your organisation' using errcode = '42501'; end if;
  new.updated_at := now(); new.updated_by := auth.uid(); return new;
end $$;

drop trigger if exists trg_product_costs_guard on product_costs;

create trigger trg_product_costs_guard before insert or update on product_costs for each row execute function public.product_costs_guard();

do $$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'products' and column_name = 'cost_price') then
    insert into product_costs (product_id, org_id, cost_price) select id, org_id, cost_price from products where cost_price is not null on conflict do nothing;
    alter table products drop column cost_price;
  end if;
end $$;


-- >>> 20261126030000_branch_overview.sql
-- Owner / manager dashboards. SECURITY INVOKER: every number respects row-level security, so a user can only ever
-- aggregate what they are allowed to read. Day boundaries use India time.
create or replace function public.branch_overview() returns table (
  branch_id uuid, branch text, today_sales numeric, today_orders int, month_sales numeric, month_orders int, month_collected numeric,
  low_stock int, open_repairs int, lab_pending int)
language sql stable security invoker set search_path = public as $$
  with d as (select (now() at time zone 'Asia/Kolkata')::date as today, date_trunc('month', now() at time zone 'Asia/Kolkata')::date as m0)
  select b.id, b.name,
    coalesce((select sum(s.grand_total) from sales s, d where s.branch_id = b.id and s.kind = 'order' and s.status <> 'cancelled' and (s.created_at at time zone 'Asia/Kolkata')::date = d.today), 0),
    (select count(*)::int from sales s, d where s.branch_id = b.id and s.kind = 'order' and s.status <> 'cancelled' and (s.created_at at time zone 'Asia/Kolkata')::date = d.today),
    coalesce((select sum(s.grand_total) from sales s, d where s.branch_id = b.id and s.kind = 'order' and s.status <> 'cancelled' and (s.created_at at time zone 'Asia/Kolkata')::date >= d.m0), 0),
    (select count(*)::int from sales s, d where s.branch_id = b.id and s.kind = 'order' and s.status <> 'cancelled' and (s.created_at at time zone 'Asia/Kolkata')::date >= d.m0),
    coalesce((select sum(s.paid_total) from sales s, d where s.branch_id = b.id and s.kind = 'order' and s.status <> 'cancelled' and (s.created_at at time zone 'Asia/Kolkata')::date >= d.m0), 0),
    (select count(*)::int from stock k where k.branch_id = b.id and k.reorder_level > 0 and k.qty <= k.reorder_level),
    (select count(*)::int from repairs r where r.branch_id = b.id and r.status in ('pending', 'in_progress')),
    (select count(*)::int from sales s where s.branch_id = b.id and s.kind = 'order' and s.status in ('lab_pending', 'in_workshop', 'qc'))
  from branches b where b.org_id = public.current_org() and b.is_active order by b.name $$;

-- Daily sales for the last N days (India time), one branch or all when p_branch is null.
create or replace function public.sales_trend(p_branch uuid default null, p_days int default 14) returns table (day date, amount numeric, orders int)
language sql stable security invoker set search_path = public as $$
  select g::date, coalesce(sum(s.grand_total), 0), count(s.id)::int
  from generate_series((now() at time zone 'Asia/Kolkata')::date - (least(greatest(p_days, 1), 90) - 1), (now() at time zone 'Asia/Kolkata')::date, interval '1 day') g
  left join sales s on s.kind = 'order' and s.status <> 'cancelled' and (s.created_at at time zone 'Asia/Kolkata')::date = g::date
       and (p_branch is null or s.branch_id = p_branch) and s.org_id = public.current_org()
  group by 1 order by 1 $$;

grant execute on function public.branch_overview() to authenticated;

grant execute on function public.sales_trend(uuid, int) to authenticated;

-- ITC summary that honours the branch switcher (null = all branches). SECURITY INVOKER respects RLS.
create or replace function public.itc_summary_scoped(p_branch uuid default null) returns table (
  period text, invoice_count int, total_purchases numeric, eligible_cgst numeric, eligible_sgst numeric, eligible_igst numeric, total_itc numeric, claimed_itc numeric)
language sql stable security invoker set search_path = public as $$
  select to_char(invoice_date, 'YYYY-MM'), count(*)::int, sum(grand_total)::numeric(14,2),
    sum(case when itc_eligible then cgst_amount else 0 end)::numeric(14,2), sum(case when itc_eligible then sgst_amount else 0 end)::numeric(14,2),
    sum(case when itc_eligible then igst_amount else 0 end)::numeric(14,2), sum(case when itc_eligible then cgst_amount + sgst_amount + igst_amount else 0 end)::numeric(14,2),
    sum(case when itc_claimed then cgst_amount + sgst_amount + igst_amount else 0 end)::numeric(14,2)
  from purchase_invoices where status != 'cancelled' and org_id = public.current_org() and (p_branch is null or branch_id = p_branch)
  group by 1 $$;

grant execute on function public.itc_summary_scoped(uuid) to authenticated;


-- >>> 20261127000000_fix_rbac_function_signatures.sql
-- Repair RBAC function signatures on databases where the earlier migrations
-- were partially applied or the invite_staff overloads both exist.

-- Drop both overloads first so future name-only GRANT/REVOKE statements cannot
-- be ambiguous. The canonical ERP API is the single-branch variant.
drop function if exists public.invite_staff(text, text, uuid[]);

drop function if exists public.invite_staff(text, text, uuid);

create function public.invite_staff(p_email text, p_role text, p_branch uuid default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  c profiles;
  v_id uuid;
  v_email text := lower(trim(p_email));
begin
  select * into c from profiles where id = auth.uid() and is_approved and not deactivated;
  if not found or c.role_key not in ('owner', 'admin') then
    raise exception 'Only owners and admins can invite staff' using errcode = '42501';
  end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter a valid email'; end if;
  if p_role not in ('admin', 'branch_manager', 'staff') then raise exception 'Invalid role'; end if;
  if c.role_key <> 'owner' and p_role = 'admin' then
    raise exception 'Only an owner can invite admins' using errcode = '42501';
  end if;
  if p_role in ('branch_manager', 'staff') and p_branch is null then raise exception 'Choose a branch'; end if;
  if p_branch is not null and not exists (
    select 1 from branches where id = p_branch and org_id = c.org_id and is_active
  ) then raise exception 'Branch not in your organisation'; end if;

  update staff_invitations set revoked_at = now()
  where org_id = c.org_id and lower(email) = v_email and accepted_at is null and revoked_at is null;
  insert into staff_invitations (org_id, email, role_key, branch_id)
  values (c.org_id, v_email, p_role, p_branch)
  returning id into v_id;
  return v_id;
end $$;

-- Existing deployments may have p_perm while others have p_permission. Drop
-- the exact signature first because PostgreSQL cannot rename input parameters
-- through CREATE OR REPLACE FUNCTION.
drop function if exists public.set_role_permission(text, text, boolean);

create function public.set_role_permission(p_role text, p_permission text, p_allowed boolean)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'Only owners and admins can change permissions' using errcode = '42501';
  end if;
  insert into role_permissions (org_id, role_key, permission, allowed)
  values (public.current_org(), p_role, p_permission, p_allowed)
  on conflict (org_id, role_key, permission)
  do update set allowed = excluded.allowed, updated_by = auth.uid(), updated_at = now();
end $$;

revoke execute on function public.invite_staff(text, text, uuid) from public, anon;

grant execute on function public.invite_staff(text, text, uuid) to authenticated;

revoke execute on function public.set_role_permission(text, text, boolean) from public, anon;

grant execute on function public.set_role_permission(text, text, boolean) to authenticated;


-- >>> 20261127010000_ops_permissions.sql
create or replace function public.approve_transfer(p_id uuid) returns void language plpgsql security definer set search_path = public as $$
declare t branch_transfers;
begin
  select * into t from branch_transfers where id = p_id and org_id = public.current_org() for update;
  if not found or t.status <> 'requested' then raise exception 'Transfer is not awaiting approval'; end if;
  if not (public.is_manager() and public.can_access_branch(t.from_branch) and public.has_perm('transfers_approve')) then raise exception 'You are not allowed to approve transfers from this branch' using errcode = '42501'; end if;
  if t.requested_by = auth.uid() and not public.is_admin() then raise exception 'You cannot approve your own request' using errcode = '42501'; end if;
  insert into stock_movements (org_id, branch_id, product_id, delta, reason, note) values (t.org_id, t.from_branch, t.product_id, -t.qty, 'transfer_out', 'Transfer ' || t.id);
  update branch_transfers set status = 'in_transit', approved_by = auth.uid(), approved_at = now() where id = t.id;
end $$;

-- Website orders: forward-only fulfilment steps, only for online-paid orders of a branch the caller can write to.
create or replace function public.advance_web_order(p_sale uuid, p_status text) returns void language plpgsql security definer set search_path = public as $$
declare s sales; rank constant text[] := array['lab_pending', 'in_workshop', 'qc', 'ready', 'delivered'];
begin
  if not public.has_perm('web_orders') then raise exception 'You are not allowed to manage website orders' using errcode = '42501'; end if;
  if p_status <> all (rank[2:5]) then raise exception 'Invalid status'; end if;
  select * into s from sales where id = p_sale and org_id = public.current_org() and kind = 'order' for update;
  if not found or not exists (select 1 from online_payments where sale_id = s.id) then raise exception 'Website order not found'; end if;
  if not public.can_access_branch(s.branch_id) then raise exception 'Not authorised for this branch' using errcode = '42501'; end if;
  if array_position(rank, s.status) is null or array_position(rank, p_status) <= array_position(rank, s.status) then raise exception 'Order cannot move to that status' ; end if;
  update sales set status = p_status, updated_at = now() where id = s.id;
end $$;

revoke execute on function public.advance_web_order from anon, public;

grant execute on function public.advance_web_order to authenticated;


-- >>> 20261128000000_data_driven_workflows.sql
-- Data-backed workflow foundations: priced checkout quotes, stock audits,
-- configurable operational permissions, and subscription entitlement records.

-- Quote snapshots created by the server before contacting Razorpay. Never expose
-- this table through anon/authenticated Data API roles.
create table if not exists public.checkout_quotes (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  quote jsonb not null,
  amount_minor bigint not null check (amount_minor > 0),
  currency text not null default 'INR' check (currency = 'INR'),
  razorpay_order_id text unique,
  status text not null default 'created' check (status in ('created','paid','consumed','expired','failed')),
  expires_at timestamptz not null default now() + interval '20 minutes',
  consumed_at timestamptz,
  sale_id uuid references public.sales(id),
  created_at timestamptz not null default now()
);

alter table public.checkout_quotes enable row level security;

revoke all on public.checkout_quotes from anon, authenticated;

grant select, insert, update, delete on public.checkout_quotes to service_role;

create index if not exists checkout_quotes_expiry on public.checkout_quotes(status, expires_at);

create unique index if not exists sales_idempotency_org_key on public.sales(org_id, idempotency_key) where idempotency_key is not null;

-- Physical cycle count with an immutable expected-stock snapshot and atomic approval.
create table if not exists public.stock_audit_sessions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.current_org() references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id),
  title text not null check (length(trim(title)) between 2 and 120),
  brand_id uuid references public.brands(id),
  shelf_location text,
  status text not null default 'counting' check (status in ('counting','submitted','approved','cancelled')),
  started_by uuid not null default auth.uid() references public.profiles(id),
  submitted_at timestamptz,
  approved_by uuid references public.profiles(id),
  approved_at timestamptz,
  created_at timestamptz not null default now(),
  check (approved_by is null or approved_by <> started_by)
);

create table if not exists public.stock_audit_lines (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.current_org() references public.organizations(id) on delete cascade,
  session_id uuid not null references public.stock_audit_sessions(id) on delete cascade,
  product_id uuid not null references public.products(id),
  expected_qty integer not null check (expected_qty >= 0),
  counted_qty integer check (counted_qty is null or counted_qty >= 0),
  counted_by uuid references public.profiles(id),
  counted_at timestamptz,
  unique(session_id, product_id)
);

create unique index if not exists branches_id_org_unique on public.branches(id, org_id);

-- Every transition, branch and expected quantity is enforced by the database.
do $$ begin
  if not exists (select 1 from pg_constraint where conrelid='public.stock_audit_sessions'::regclass and conname='stock_audit_branch_org_fk') then
    alter table public.stock_audit_sessions add constraint stock_audit_branch_org_fk foreign key (branch_id, org_id) references public.branches(id, org_id) not valid;
  end if;
end $$;

alter table public.stock_audit_sessions validate constraint stock_audit_branch_org_fk;

create or replace function public.guard_stock_audit_line() returns trigger
language plpgsql set search_path = public as $$
declare s public.stock_audit_sessions%rowtype;
begin
  select * into s from public.stock_audit_sessions where id = coalesce(new.session_id, old.session_id) for update;
  if not found or s.status <> 'counting' or s.org_id <> public.current_org() or not public.can_access_branch(s.branch_id) then
    raise exception 'Stock count is locked or not accessible' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    if not exists (select 1 from public.products p where p.id = new.product_id and p.org_id = s.org_id and p.status = 'active') then
      raise exception 'Product is not active in this organisation';
    end if;
    select qty into new.expected_qty from public.stock where org_id=s.org_id and branch_id=s.branch_id and product_id=new.product_id;
    new.expected_qty := coalesce(new.expected_qty,0);
    new.org_id := s.org_id;
  elsif tg_op = 'UPDATE' then
    if new.session_id <> old.session_id or new.product_id <> old.product_id or new.expected_qty <> old.expected_qty then
      raise exception 'Count line identity and expected quantity are immutable';
    end if;
    new.org_id := old.org_id;
    new.counted_by := auth.uid(); new.counted_at := now();
  end if;
  return coalesce(new, old);
end $$;

-- Session lifecycle and branch identity are enforced in the database so direct
-- table writes cannot bypass the submit/approve workflow or move a count.
create or replace function public.guard_stock_audit_session() returns trigger
language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is null or new.org_id <> public.current_org() or new.started_by <> auth.uid()
       or new.status <> 'counting' or new.submitted_at is not null
       or new.approved_by is not null or new.approved_at is not null
       or not public.has_perm('stock_audit') or not public.can_access_branch(new.branch_id) then
      raise exception 'Invalid or unauthorised stock audit session' using errcode='42501';
    end if;
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id or new.org_id is distinct from old.org_id
       or new.branch_id is distinct from old.branch_id or new.title is distinct from old.title
       or new.brand_id is distinct from old.brand_id or new.shelf_location is distinct from old.shelf_location
       or new.started_by is distinct from old.started_by or new.created_at is distinct from old.created_at then
      raise exception 'Stock audit identity and scope are immutable';
    end if;
    if old.status = 'counting' and new.status = 'submitted' then
      if auth.uid() <> old.started_by or not public.has_perm('stock_audit')
         or exists (select 1 from public.stock_audit_lines where session_id=old.id and counted_qty is null) then
        raise exception 'Every line must be counted by the session owner before submission' using errcode='42501';
      end if;
      new.submitted_at := now(); new.approved_by := null; new.approved_at := null;
    elsif old.status = 'submitted' and new.status = 'approved' then
      if auth.uid() is null or auth.uid() = old.started_by or not public.is_manager()
         or not public.has_perm('stock_audit') or new.approved_by is distinct from auth.uid() then
        raise exception 'Only another authorised manager can approve this stock count' using errcode='42501';
      end if;
      new.approved_at := now();
    else
      raise exception 'Invalid stock audit state transition';
    end if;
    return new;
  end if;
  raise exception 'Stock audit sessions cannot be deleted';
end $$;

do $$
declare definition text; needle text := $n$if v_idem is not null and v_idem <> '' then$n$;
begin
  select pg_get_functiondef('public.place_sale(jsonb)'::regprocedure) into definition;
  if position('pg_advisory_xact_lock(hashtextextended(v_org::text || v_idem, 0))' in definition) = 0 then
    if position(needle in definition) = 0 then raise exception 'Could not locate place_sale idempotency guard'; end if;
    definition := replace(definition, needle, needle || E'\n    perform pg_advisory_xact_lock(hashtextextended(v_org::text || v_idem, 0));');
    execute definition;
  end if;
end $$;

do $$
declare definition text;
begin
  select pg_get_functiondef('public.place_sale(jsonb)'::regprocedure) into definition;
  definition := replace(definition, 'where org_id = public.current_org() and key = ''gst_enabled''', 'where org_id = v_org and key = ''gst_enabled''');
  definition := replace(definition, 'where org_id = public.current_org() and key = ''lab_lead_days''', 'where org_id = v_org and key = ''lab_lead_days''');
  if position('where org_id = v_org and key = ''gst_enabled''' in definition) = 0 or position('where org_id = v_org and key = ''lab_lead_days''' in definition) = 0 then
    raise exception 'Could not bind storefront sale settings to the quote organisation';
  end if;
  execute definition;
end $$;

